module TopModule (
    input  logic       clk,
    input  logic       reset,
    input  logic [2:0] s,
    output logic       fr2,
    output logic       fr1,
    output logic       fr0,
    output logic       dfr
);

    logic [1:0] input_lvl;
    logic [1:0] curr_lvl, prev_lvl;

    always_comb begin
        case (s)
            3'b111: input_lvl = 2'd3;
            3'b011: input_lvl = 2'd2;
            3'b001: input_lvl = 2'd1;
            3'b000: input_lvl = 2'd0;
            default: input_lvl = 2'd0;
        endcase
    end

    always_ff @(posedge clk) begin
        if (reset) begin
            curr_lvl <= 2'd0;
            prev_lvl <= 2'd0;
        end else begin
            if (input_lvl != curr_lvl) begin
                prev_lvl <= curr_lvl;
                curr_lvl <= input_lvl;
            end
        end
    end

    always_comb begin
        fr2 = 1'b0;
        fr1 = 1'b0;
        fr0 = 1'b0;
        dfr = 1'b0;

        case (curr_lvl)
            2'd3: begin
                fr2 = 1'b0;
                fr1 = 1'b0;
                fr0 = 1'b0;
                dfr = 1'b0;
            end
            2'd2: begin
                fr2 = 1'b0;
                fr1 = 1'b0;
                fr0 = 1'b1;
                dfr = (prev_lvl < curr_lvl);
            end
            2'd1: begin
                fr2 = 1'b0;
                fr1 = 1'b1;
                fr0 = 1'b1;
                dfr = (prev_lvl < curr_lvl);
            end
            2'd0: begin
                fr2 = 1'b1;
                fr1 = 1'b1;
                fr0 = 1'b1;
                dfr = 1'b1;
            end
            default: begin
                fr2 = 1'b0;
                fr1 = 1'b0;
                fr0 = 1'b0;
                dfr = 1'b0;
            end
        endcase
    end

endmodule

