module tb_TopModule;

    logic       clk;
    logic       reset;
    logic [2:0] s;
    logic       fr2;
    logic       fr1;
    logic       fr0;
    logic       dfr;

    // Instantiate TopModule
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .s(s),
        .fr2(fr2),
        .fr1(fr1),
        .fr0(fr0),
        .dfr(dfr)
    );

    // Clock generation
    initial clk = 0;
    always #5 clk = ~clk;

    task check(input logic exp_fr2, input logic exp_fr1, input logic exp_fr0, input logic exp_dfr, input string msg);
        begin
            #1; // allow combinatorial propagation
            if (fr2 !== exp_fr2 || fr1 !== exp_fr1 || fr0 !== exp_fr0 || dfr !== exp_dfr) begin
                $display("SELFTEST FAIL: %s. Expected fr2=%b, fr1=%b, fr0=%b, dfr=%b; Got fr2=%b, fr1=%b, fr0=%b, dfr=%b (s=%b)",
                         msg, exp_fr2, exp_fr1, exp_fr0, exp_dfr, fr2, fr1, fr0, dfr, s);
                $finish;
            end
        end
    endtask

    initial begin
        s = 3'b000;
        reset = 1;
        #12;
        check(1, 1, 1, 1, "Reset test");

        reset = 0;
        #10;
        // Still at level 0 (s = 3'b000)
        check(1, 1, 1, 1, "Level 0 initial");

        // Rise to level 1 (s = 3'b001)
        s = 3'b001;
        #10; // clock edge 1
        // Now at level 1, previous was 0. prev < curr (0 < 1) -> dfr = 1
        check(0, 1, 1, 1, "Level 1 rising");

        // Rise to level 2 (s = 3'b011)
        s = 3'b011;
        #10; // clock edge 2
        // Now at level 2, previous was 1. prev < curr (1 < 2) -> dfr = 1
        check(0, 0, 1, 1, "Level 2 rising");

        // Rise to level 3 (s = 3'b111)
        s = 3'b111;
        #10; // clock edge 3
        // Above s[2], all zero
        check(0, 0, 0, 0, "Level 3 above s[2]");

        // Fall to level 2 (s = 3'b011)
        s = 3'b011;
        #10; // clock edge 4
        // Now at level 2, previous was 3. prev < curr (3 < 2 is false) -> dfr = 0
        check(0, 0, 1, 0, "Level 2 falling");

        // Fall to level 1 (s = 3'b001)
        s = 3'b001;
        #10; // clock edge 5
        // Now at level 1, previous was 2. prev < curr (2 < 1 is false) -> dfr = 0
        check(0, 1, 1, 0, "Level 1 falling");

        // Fall to level 0 (s = 3'b000)
        s = 3'b000;
        #10; // clock edge 6
        // Below s[0], max flow
        check(1, 1, 1, 1, "Level 0 falling");

        $display("SELFTEST PASS");
        $finish;
    end

endmodule
